face.layout_source:
// feed-forward-compressor.face: the panel for tap/examples/compressors/feed-forward-compressor.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/compressors/feed-forward-compressor.face --meta <graph>.cragmeta

face "Feed-Forward Compressor" {
  row(gap = 10) {
    box "Detector" { knob.big "Threshold" (threshold) knob "Ratio" (ratio) knob "Attack" (attack) knob "Release" (release) }
    box "Output" { knob "Makeup" (makeup) vslider "Wet" (wet) vslider "Dry" (dry) }
    viz(grow = 1)
  }
}
